export const createCIBucket={name:"开通数据万象",fn:function(){const o=`https://${config.Bucket}.pic.${config.Region}.myqcloud.com`;cos.request({Method:"PUT",Url:o},function(o,e){o?console.log(o):console.log(e.Response)})}};export const deleteCIBucket={name:"关闭数据万象",fn:function(){const o=`https://${config.Bucket}.pic.${config.Region}.myqcloud.com`;cos.request({Method:"PUT",Url:o,Action:"unbind"},function(o,e){o?console.log(o):console.log(e.Response)})}};export const queryCIBucket={name:"查询查询数据处理服务",fn:function(){const o=`https://${config.Bucket}.pic.${config.Region}.myqcloud.com`;cos.request({Method:"GET",Url:o},function(o,e){o?console.log(o):console.log(e)})}};export const postVirusDetect={name:"提交病毒检测任务",fn:function(){const o="https://"+config.Bucket+".ci."+config.Region+".myqcloud.com/virus/detect",e=COS.util.json2xml({Request:{Input:{Object:"test/1.png"},Conf:{DetectType:"Virus"}}});cos.request({Method:"POST",Key:"virus/detect",Url:o,Body:e,ContentType:"application/xml"},function(o,e){o?console.log(o):console.log(e)})}};export const getVirusDetectResult={name:"查询病毒检测任务结果",fn:function(){const o="ssdb2dab23bcdb11ed9efb5254009411xx",e="https://"+config.Bucket+".ci."+config.Region+".myqcloud.com/virus/detect/"+o;cos.request({Method:"GET",Key:"virus/detect/"+o,Url:e},function(o,e){o?console.log(o):console.log(e)})}};export const describeRefer={name:"查询防盗链",fn:function(){const o="https://"+config.Bucket+".pic."+config.Region+".myqcloud.com/?hotlink";cos.request({Method:"GET",Url:o},function(o,e){o?console.log(o):console.log(e)})}};export const setRefer={name:"设置防盗链",fn:function(){const o="https://"+config.Bucket+".pic."+config.Region+".myqcloud.com/?hotlink",e=COS.util.json2xml({Hotlink:{Url:"https://www.example.com",Type:"white"}});cos.request({Method:"PUT",Url:o,Body:e,ContentType:"application/xml"},function(o,e){o?console.log(o):console.log(e)})}};